/*! 
 * Simple XSS sanitizer - Basic replacement for DOMPurify
 * For production use, please use the official DOMPurify library
 */
window.DOMPurify = {
    sanitize: function(html) {
        if (!html) return '';
        
        // Create a temporary div to parse HTML
        const temp = document.createElement('div');
        temp.innerHTML = html;
        
        // Remove all script tags
        const scripts = temp.querySelectorAll('script');
        scripts.forEach(script => script.remove());
        
        // Remove dangerous attributes
        const dangerousAttrs = ['onclick', 'onload', 'onerror', 'onmouseover', 'onmouseout', 'onfocus', 'onblur', 'onchange', 'onsubmit', 'javascript:'];
        const allElements = temp.querySelectorAll('*');
        allElements.forEach(el => {
            // Remove dangerous attributes
            Array.from(el.attributes).forEach(attr => {
                if (dangerousAttrs.some(dangerous => attr.name.toLowerCase().includes(dangerous.toLowerCase()))) {
                    el.removeAttribute(attr.name);
                }
                if (attr.value && attr.value.toLowerCase().includes('javascript:')) {
                    el.removeAttribute(attr.name);
                }
            });
            
            // Remove dangerous tags
            if (['script', 'iframe', 'object', 'embed', 'form', 'input'].includes(el.tagName.toLowerCase())) {
                el.remove();
            }
        });
        
        return temp.innerHTML;
    }
};